adjustSynchronization(currentTime) {
    if (this.speechQueue.length <= 0) return;

    const nextSpeechTime = this.speechQueue[0].startTime;
    const timeDifference = nextSpeechTime - currentTime;

    // Zonas mortas (Deadzones)
    const upperBound = 500 + 200; // Zona superior
    const lowerBound = 1000 - 200; // Zona inferior

    if (timeDifference < lowerBound || timeDifference >= upperBound) {
         if (this.dubbingMode === 'advanced') {
            const maxSpeed = parseFloat(this.maxSpeedControl.value) || 1;

            if (timeDifference < 500) {
                 this.speedControl.value = maxSpeed;
                 if (this.speakingControlMode === 'slowDown') this.video.playbackRate = Math.min(this.video.playbackRate + 0.1, 0.2);
            } else {
                 this.speedControl.value = 1.2;
                 if (this.speakingControlMode === 'slowDown') this.video.playbackRate = Math.max(this.video.playbackRate - 0.1, 1.0);
            }
            this.updateRangeValue('speed');
         }
    }
}
