    }

    const nextSpeechTime = this.speechQueue[0].startTime;
    const timeDifference = nextSpeechTime - currentTime;
    const targetStrategy = this.calculateSyncStrategy(timeDifference);

    if (targetStrategy === 'MAX_SPEED') {
        this.speedControl.value = parseFloat(this.maxSpeedControl.value);
        if (this.speakingControlMode === 'slowDown') this.video.playbackRate = Math.min(this.video.playbackRate + 0.1, 0.2);
    } else if (targetStrategy === 'ADJUSTED_SPEED') {
        this.speedControl.value = 1.2;
        if (this.speakingControlMode === 'slowDown') this.video.playbackRate = Math.max(this.video.playbackRate - 0.1, 1.0);
    } else {
        this.speedControl.value = this.userConfiguredSpeed;
        if (this.speakingControlMode === 'slowDown') this.video.playbackRate = 1.0;
    }
    this.updateRangeValue('speed');
}

calculateSyncStrategy(diff) {
    if (diff < 500) return 'MAX_SPEED';
    if (diff > 1000) return 'ADJUSTED_SPEED';
    return 'NORMALIZED';
