                await this.delayVideoAdjustment(-0.1, 1.0);
            }
        } else {
            this.speedControl.value = this.userConfiguredSpeed;
            if (this.speakingControlMode === 'slowDown') {
                 await this.setVideoStandardSpeed(1.0);
            }
        }
        this.updateRangeValue('speed');
        return true;
    }
    return false;
}

// Auxiliares assíncronos para demonstração (usam setTimeout microtask friendly)
delayVideoAdjustment(change, target) {
    return new Promise(resolve => {
        setTimeout(() => {
            this.video.playbackRate = Math.min(Math.max(this.video.playbackRate + change, target - 0.01), target);
            resolve(true);
        }, 1);
    });
}
